","import React, { useState, useEffect } from "react";
import ReactDOM from "react-dom/client";

const API_URL = "/api/x_2056099_indust_0/dashboard_api/kpis";
const ALERTS_PAGE = "x_2056099_indust_0_alerts_center.do";

interface AlertSummary {
 critical: number;
 high: number;
 medium: number;
 low: number;
 open: number;
}

interface KpiData {
 alerts: { critical: number; high: number; open: number };
}

const CARDS: {
 key: keyof AlertSummary;
 label: string;
 borderColor: string;
 countColor: string;
}[] = [
 {
 key: "critical",
 label: "Critical",
 borderColor: "rgb(var(--now-indicator--primary_critical--background-color,229,34,57))",
 countColor: "rgb(var(--now-indicator--primary_critical--background-color,229,34,57))",
 },
 {
 key: "high",
 label: "High",
 borderColor: "rgb(235,117,27)",
 countColor: "rgb(235,117,27)",
 },
 {
 key: "medium",
 label: "Medium",
 borderColor: "rgb(var(--now-indicator--primary_warning--background-color,204,158,0))",
 countColor: "rgb(var(--now-indicator--primary_warning--background-color,204,158,0))",
 },
 {
 key: "low",
 label: "Low",
 borderColor: "rgb(var(--now-indicator--primary_positive--background-color,62,134,0))",
 countColor: "rgb(var(--now-indicator--primary_positive--background-color,62,134,0))",
 },
];

function AlertSummaryWidget() {
 const [data, setData] = useState<AlertSummary>({
 critical: 0, high: 0, medium: 0, low: 0, open: 0,
 });
 const [loading, setLoading] = useState(true);

 useEffect(() => {
 const token = (window as any).g_ck || "";
 fetch(API_URL, {
 headers: { Accept: "application/json", "X-UserToken": token },
 })
 .then((r) => r.json())
 .then((json) => {
 const a = json?.result?.alerts || {};
 setData({
 critical: a.critical || 0,
 high: a.high || 0,
 medium: 0,
 low: 0,
 open: a.open || 0,
 });
 /* The KPIs endpoint doesn't return medium/low breakdown,
 so fetch from the alert center API for accurate counts */
 return fetch(
 "/api/x_2056099_indust_0/alert_center_api/alerts?limit=1",
 { headers: { Accept: "application/json", "X-UserToken": token } }
 );
 })
 .then((r) => r.json())
 .then((json) => {
 const s = json?.result?.summary;
 if (s) {
 setData((prev) => ({
 ...prev,
 critical: s.critical ?? prev.critical,
 high: s.high ?? prev.high,
 medium: s.medium ?? 0,
 low: s.low ?? 0,
 open: s.open ?? prev.open,
 }));
 }
 })
 .catch((e) => console.error("Alert summary fetch error:", e))
 .finally(() => setLoading(false));
 }, []);

 const totalActive = data.critical + data.high + data.medium + data.low;

 return (
 <div style={styles.container}>
 <div style={styles.header}>
 <div>
 <h2 style={styles.title}>Alerts & Exceptions</h2>
 <p style={styles.subtitle}>
 {totalActive > 0
 ? `${totalActive} active alert${totalActive !== 1 ? "s" : ""} requiring attention`
 : "No active alerts — all systems nominal"}
 </p>
 </div>
 <button
 style={styles.viewAllBtn}
 onClick={() => window.open(ALERTS_PAGE, "_blank")}
 onMouseOver={(e) =>
 ((e.currentTarget as HTMLElement).style.opacity = "0.85")
 }
 onMouseOut={(e) =>
 ((e.currentTarget as HTMLElement).style.opacity = "1")
 }
 >
 View All Alerts →
 </button>
 </div>

 {loading ? (
 <div style={styles.loadingRow}>
 <div style={styles.spinner} />
 </div>
 ) : (
 <div style={styles.cardRow}>
 {CARDS.map((c) => (
 <div
 key={c.key}
 style={{
 ...styles.card,
 borderTop: `3px solid ${c.borderColor}`,
 }}
 >
 <span style={{ ...styles.count, color: c.countColor }}>
 {data[c.key]}
 </span>
 <span style={styles.label}>{c.label}</span>
 </div>
 ))}
 </div>
 )}

 {!loading && data.critical > 0 && (
 <div style={styles.criticalBanner}>
 ⚠ {data.critical} critical alert{data.critical !== 1 ? "s" : ""} — immediate action recommended.{" "}
 <a
 style={styles.bannerLink}
 href={`${ALERTS_PAGE}?severity=critical`}
 target="_blank"
 rel="noopener noreferrer"
 >
 Review now
 </a>
 </div>
 )}
 </div>
 );
}

const styles: Record<string, React.CSSProperties> = {
 container: {
 maxWidth: "1400px",
 margin: "0 auto 1.5rem",
 padding: "1.25rem 1.5rem",
 background: "rgb(var(--now-color_background--primary,255,255,255))",
 borderRadius: "var(--now-container--border-radius,8px)",
 border: "1px solid rgb(var(--now-container--border-color,207,213,215))",
 boxShadow: "var(--now-static-drop-shadow--sm)",
 fontFamily: "var(--now-font-family,system-ui,sans-serif)",
 },
 header: {
 display: "flex",
 justifyContent: "space-between",
 alignItems: "flex-start",
 marginBottom: "1rem",
 },
 title: {
 margin: "0 0 0.25rem",
 fontSize: "var(--now-static-font-size--lg,1.25rem)",
 fontWeight: "700",
 color: "rgb(var(--now-color_text--primary,16,23,26))",
 },
 subtitle: {
 margin: 0,
 fontSize: "var(--now-static-font-size--sm,0.75rem)",
 color: "rgb(var(--now-color_text--secondary,75,85,89))",
 },
 viewAllBtn: {
 display: "inline-flex",
 alignItems: "center",
 padding: "0.5rem 1rem",
 background: "rgb(var(--now-actionable--primary--background-color,0,128,163))",
 color: "rgb(var(--now-actionable_label--primary--color,255,255,255))",
 border: "none",
 borderRadius: "var(--now-actionable--border-radius,6px)",
 fontSize: "var(--now-static-font-size--sm,0.75rem)",
 fontWeight: "600",
 cursor: "pointer",
 whiteSpace: "nowrap",
 transition: "opacity 100ms",
 },
 cardRow: {
 display: "grid",
 gridTemplateColumns: "repeat(4, 1fr)",
 gap: "0.75rem",
 },
 card: {
 display: "flex",
 flexDirection: "column",
 alignItems: "center",
 padding: "1rem",
 borderRadius: "var(--now-container--border-radius,8px)",
 border: "1px solid rgb(var(--now-container--border-color,207,213,215))",
 background: "rgb(var(--now-color_background--primary,255,255,255))",
 },
 count: {
 fontSize: "1.75rem",
 fontWeight: "700",
 lineHeight: "1.2",
 },
 label: {
 fontSize: "0.6875rem",
 color: "rgb(var(--now-color_text--secondary,75,85,89))",
 marginTop: "0.375rem",
 textTransform: "uppercase" as const,
 letterSpacing: "0.05em",
 },
 criticalBanner: {
 marginTop: "0.75rem",
 padding: "0.625rem 1rem",
 borderRadius: "var(--now-container--border-radius,8px)",
 background: "rgba(var(--now-indicator--primary_critical--background-color,229,34,57),0.08)",
 color: "rgb(var(--now-indicator--primary_critical--background-color,229,34,57))",
 fontSize: "var(--now-static-font-size--sm,0.75rem)",
 fontWeight: "500",
 },
 bannerLink: {
 color: "inherit",
 fontWeight: "700",
 textDecoration: "underline",
 },
 loadingRow: {
 display: "flex",
 justifyContent: "center",
 padding: "2rem",
 },
 spinner: {
 width: "1.5rem",
 height: "1.5rem",
 border: "3px solid rgba(0,128,163,0.2)",
 borderTopColor: "rgb(0,128,163)",
 borderRadius: "50%",
 animation: "spin 1s linear infinite",
 },
};

// Mount into the dashboard
const mountPoint = document.getElementById("alert-summary");
if (mountPoint) {
 ReactDOM.createRoot(mountPoint).render(<AlertSummaryWidget />);
}
